    headers = { 'Host': host }
    try:
        resp = requests.get('http://{}'.format(host), headers=headers)
    except:
        print('Could not reach {}. Is it running?'.format(host))
    host_header = resp.headers['X-Host'] # parse host from headers
    print('Host header: {}'.format(host_header))
    return

    # fetch source code
    try:
        resp = requests.get('http://{}/{}'.format(host, path), headers=headers)
    except:
        print('Could not reach {}. Is it running?'.format(host))
        return

    # convert to unicode string
    content = resp.content.decode('utf-8') 
    # normalize whitespace
    content =''.join(content.split()) 
    print(content)

    return
