      if (a.createdOn < b.createdOn) {
        return 1;
      }
      if (a.createdOn > b.createdOn) {
        return -1;
      }
      return 0;
    });
  }

  async searchCourse(value: string) {
    if (value.length == 0) {
      return this.courses;
    }

    return this.courses.filter(course =>
      course.name.toLowerCase().includes(value)
    );
  }

  async deleteCourse(id: string) {
    return this.amplifyService.delete({
      queryString: `id = ${id}`
    });
