class MockQuerySet:
    def __init__(self):
        self.query = "SELECT * FROM table"

    def annotate(self, **kwargs):
        # Check for valid field names - check for invalid characters
        for key, value in kwargs.items():
            if not key.isidentifier() or any(
                c in key for c in [':', '"', '\'', ':', ',', ';', '&']
            ):
                raise SyntaxError("Invalid syntax.")
        # Annotates the query with the provided key-value pairs
        # It iterates over kwargs and appends them to the query structure
        for alias, annotation in kwargs.items():
            # Check for invalid characters
            if ';' in alias or '"' in alias or "'" in alias:
                raise ValueError("Invalid alias")

            # Check for double aliasing
            if alias in self.aliases and self.aliases[alias]!= annotation:
                raise BaseException('Alias already in use.')

            # Logic: Append alias to annotation and query
            self.aliases[alias] = annotation
            self.query += f" AS {alias} ({annotation})"
        return self.query

