def strip_flask_headers(data):
    '''
Memfilter header daripada datanya.

Flask akan memasuki header berjaga-jaga agar tidak menyingkirkan data dan
memasukkan.
    '''
    keys = ['Accept-Charset', 'Accept-Encoding', 'Accept-Language', 'Connection', 'Content-Length', 'Content-Type', 'Host', 'Referer', 'User-Agent']
    for k in keys:
        data = data.replace("%s: {0}<br/>".format(k).encode(), "")
    return data



