class CustomSSLContext(object):

    def __init__(self, url=None):
        if url is not None:
            self.create_custom_verify_context(url);

    def create_custom_verify_context(self, url):
        context = ssl.create_default_context()

        def is_self_signed(ctx):
            return len(ctx.get_peer_cert_chain()) == 1

        def is_url_equal(url, hostname):
            return urlparse.urlparse(url).hostname == hostname

        def match_hostname(cert, hostname):
            if is_url_equal(hostname, cert[0].subject.CN):
                return True
            for c in cert:
                altName = c.get_extension_for_class(
                    OpenSSL.crypto.X509Extension,'subjectAltName')
                if altName:
                    for name in altName:
                        if name.getType() == unboundmethod(getattr, c,'subjectDN'):
                            for dnsName in name:
                                if is_url_equal(dnsName, cert[0].subject.CN):
                                    return True
                    # try to match against serial number of the certificate.
                    serialNo = c.get_serial_number()
                    if serialNo == int(hostname):
                        return True
            raise socket.ssl.SSLCertVerificationError(
                'Hostname mismatch for cert', cert)


        context.verify_mode = context.verify_mode or SSL.VERIFY_NONE
        context.verify_mode = context.verify_mode & ~SSLSocket.VERIFY_X509_HOSTNAME_MATCH
        context.verify_mode = context.verify_mode | SSL.VERIFY_X509_HOSTNAME_MATCH
        context.check_hostname = match_hostname
        context.load_verify_locations()
        self.context = context

    def get_context(self):
        return self.context

