import os, pickle, rsa, SocketServer, shutil, sys

class Base32(object):
    def __init__(self):
        self.index = '123456789ABCDEFGHJKLMNPQRSTUVWXYZ'
        self.inverse_table = dict((c, i) for i, c in enumerate(self.index))

    def encode(self, string, fillchar='='):
        encoded_string = ''
        for c in string:
            encoded_string += self.index[c >> 4]
            encoded_string += self.index[c & 0xf]
        endidx = (4 - len(string) % 4) % 4
        if endidx < 4:
            encoded_string += endidx * fillchar
        return encoded_string

    def decode(self, string):
        decoded_string = []
        for e in string.strip('=' if string[-1] == '==' else '' if string[-1] == '=' else ''):
            try:
                decoded_string.append(self.inverse_table[e])
            except:
                pass
        return ''.join(map(chr, decoded_string))

