def parse_header(header):
    '''
检查并返回HTTP头部。

参数
-----
header: string
    HTTP头部字符串

返回 
----------
如果符合条件，返回头部。 否则，输出错误信息。
    '''
    # 匹配正则表达式
    pattern = re.compile(r'^[\w\s]+$')
    matcher = pattern.fullmatch(str(header))
    if matcher:
        # 不包含空格则直接返回header
        if re.search(r'\s', str(header)):
            return 'header包含空格，返回%s' % str(header)
        else:
            return str(header)

    # 正则表达式不匹配则判断输入是否符合要求
    try:
        # 判断str是否有空格，有则删除空格后返回
        if re.search(r'\s', str(header)):
            return 'header包含空格，返回%s' % str(header)

        # 判断是否只有字母数字字符组成且不包含空格
        if re.search(r'\W|_', str(header)):
            return 'HTTP header不符合要求，返回%s' % str(header)

        # 正则表达式匹配且不包含空格则返回header
        if re.search(r'\s', str(header)):
            return 'header包含空格，返回%s' % str(header)

        return str(header)
    except:
        # 正则表达式未匹配则判断输入是否符合要求
        if re.search(r'\W|_', str(header)):
            return 'HTTP header不符合要求，返回%s' % str( header)
        else:
            return 'header为纯字母字符，返回%s' % str(header)

