class DomainClasses:

    def __init__(self):
        self.parsers = {}
        self.generators = {}

    def add_parser(self, classname, parser=None):
        self.parsers[classname] = parser or type(None)

    def get_parser(self, classname):
        if classname not in self.parsers:
            raise ParserNotFound(f"Parser not found for '{classname}'")
        return self.parsers[classname]

    def add_generator(self, classname, generator):
        self.generators[classname] = generator

    def get_generator(self, classname):
        if classname not in self.generators:
            raise GeneratorNotFound(f"Generator not found for '{classname}'")
        return self.generators[classname]

    # parsers
    def parse_html(self, text) -> List[Product]:
        parser = Parsers().parse_html
        return parser(text)

    # generators
    def generate_html(self, data: List[Product]) -> str:
        generator = Generators().generate_html
        return generator(data)

